type Position = {
  line: number;
  column: number;
};

type Node =
  | { type: "text"; value: string }
  | { type: "value"; path: string; escaped: boolean; position: Position }
  | {
      type: "if";
      path: string;
      then: Node[];
      otherwise: Node[];
      position: Position;
    }
  | {
      type: "each";
      path: string;
      body: Node[];
      otherwise: Node[];
      position: Position;
    };

type BlockNode = Extract<Node, { type: "if" | "each" }>;

type Frame = {
  node: BlockNode;
  parent: Node[];
  inElse: boolean;
};

type Context = {
  value: unknown;
  index: number;
};

export class TemplateError extends Error {
  readonly line: number;
  readonly column: number;

  constructor(message: string, position: Position) {
    super(`${message} at line ${position.line}, column ${position.column}`);
    this.name = "TemplateError";
    this.line = position.line;
    this.column = position.column;
  }
}

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;

  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }

  return { line, column };
}

function requirePath(path: string, kind: string, position: Position): string {
  if (!path) {
    throw new TemplateError(`${kind} requires a path`, position);
  }
  if (path.split(".").some((part) => part.length === 0)) {
    throw new TemplateError(`Invalid path "${path}"`, position);
  }
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let current = root;
  let cursor = 0;

  while (cursor < template.length) {
    const open = template.indexOf("{{", cursor);
    if (open === -1) {
      current.push({ type: "text", value: template.slice(cursor) });
      break;
    }

    if (open > cursor) {
      current.push({ type: "text", value: template.slice(cursor, open) });
    }

    const position = positionAt(template, open);
    const triple = template.startsWith("{{{", open);
    const closeToken = triple ? "}}}" : "}}";
    const contentStart = open + (triple ? 3 : 2);
    const close = template.indexOf(closeToken, contentStart);
    if (close === -1) {
      throw new TemplateError("Unclosed tag", position);
    }

    const tag = template.slice(contentStart, close).trim();
    cursor = close + closeToken.length;

    if (triple) {
      current.push({
        type: "value",
        path: requirePath(tag, "Interpolation", position),
        escaped: false,
        position,
      });
      continue;
    }

    if (tag.startsWith("!")) continue;

    if (tag.startsWith("#")) {
      const match = /^#(if|each)(?:\s+(.+?))?$/.exec(tag);
      if (!match) {
        const name = tag.slice(1).split(/\s/, 1)[0] || tag;
        throw new TemplateError(`Unknown block "${name}"`, position);
      }

      const type = match[1] as "if" | "each";
      const path = requirePath(match[2]?.trim() ?? "", `#${type}`, position);
      const node: BlockNode =
        type === "if"
          ? { type, path, then: [], otherwise: [], position }
          : { type, path, body: [], otherwise: [], position };
      current.push(node);
      stack.push({ node, parent: current, inElse: false });
      current = node.type === "if" ? node.then : node.body;
      continue;
    }

    if (tag === "else") {
      const frame = stack.at(-1);
      if (!frame) throw new TemplateError("{{else}} outside a block", position);
      if (frame.inElse) throw new TemplateError("Duplicate {{else}}", position);
      frame.inElse = true;
      current = frame.node.otherwise;
      continue;
    }

    if (tag.startsWith("/")) {
      const name = tag.slice(1).trim();
      if (name !== "if" && name !== "each") {
        throw new TemplateError(`Unknown closing block "${name}"`, position);
      }
      const frame = stack.at(-1);
      if (!frame) {
        throw new TemplateError(`Closing {{/${name}}} without an open block`, position);
      }
      if (frame.node.type !== name) {
        throw new TemplateError(
          `Mismatched closing block: expected {{/${frame.node.type}}}, got {{/${name}}}`,
          position,
        );
      }
      stack.pop();
      current = frame.parent;
      continue;
    }

    current.push({
      type: "value",
      path: requirePath(tag, "Interpolation", position),
      escaped: true,
      position,
    });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    throw new TemplateError(`Unclosed {{#${unclosed.node.type}}} block`, unclosed.node.position);
  }

  return root;
}

function property(value: unknown, parts: string[]): { found: boolean; value: unknown } {
  let current = value;
  for (const part of parts) {
    if ((typeof current !== "object" || current === null) && typeof current !== "function") {
      return { found: false, value: undefined };
    }
    if (!Object.prototype.hasOwnProperty.call(current, part)) {
      return { found: false, value: undefined };
    }
    current = (current as Record<string, unknown>)[part];
  }
  return { found: true, value: current };
}

function resolve(path: string, root: unknown, contexts: Context[]): unknown {
  if (path === "this") return contexts.at(-1)?.value;
  if (path === "@index") return contexts.at(-1)?.index;

  if (path.startsWith("this.")) {
    return property(contexts.at(-1)?.value, path.slice(5).split(".")).value;
  }

  const parts = path.split(".");
  const local = contexts.length ? property(contexts.at(-1)!.value, parts) : undefined;
  if (local?.found) return local.value;
  return property(root, parts).value;
}

function truthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return value !== "" && value !== 0 && value !== false && value != null;
}

function scalar(value: unknown, position: Position): string {
  if (value == null) return "";
  switch (typeof value) {
    case "string":
    case "number":
    case "bigint":
    case "boolean":
    case "symbol":
      return String(value);
    default:
      throw new TemplateError(
        `Cannot render ${typeof value === "function" ? "function" : "object"} value as text`,
        position,
      );
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], root: unknown, contexts: Context[]): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") {
      output += node.value;
    } else if (node.type === "value") {
      const text = scalar(resolve(node.path, root, contexts), node.position);
      output += node.escaped ? escapeHtml(text) : text;
    } else if (node.type === "if") {
      const branch = truthy(resolve(node.path, root, contexts)) ? node.then : node.otherwise;
      output += renderNodes(branch, root, contexts);
    } else {
      const value = resolve(node.path, root, contexts);
      if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          contexts.push({ value: value[index], index });
          output += renderNodes(node.body, root, contexts);
          contexts.pop();
        }
      } else {
        output += renderNodes(node.otherwise, root, contexts);
      }
    }
  }
  return output;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), data, []);
}

import { describe, expect, test } from "bun:test";
import { render, TemplateError } from "../src/engine";

describe("render", () => {
  test("interpolates escaped and raw scalar values", () => {
    const data = { value: `&<>"'`, count: 0, absent: undefined };
    expect(render("{{value}}|{{{value}}}|{{count}}|{{absent}}", data)).toBe(
      "&amp;&lt;&gt;&quot;&#39;|&<>\"'|0|",
    );
  });

  test("preserves whitespace and removes comments", () => {
    expect(render(" a\n{{! ignored }}  b ", {})).toBe(" a\n  b ");
  });

  test("handles nested conditionals and specified truthiness", () => {
    expect(render("{{#if yes}}Y{{#if no}}N{{else}}!{{/if}}{{else}}X{{/if}}", {
      yes: [1], no: [],
    })).toBe("Y!");
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    expect(render("{{#if value}}yes{{else}}no{{/if}}", { value: {} })).toBe("yes");
  });

  test("iterates nested arrays with local lookup, root fallback, this, and index", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{/each}}";
    expect(render(template, {
      title: "root",
      groups: [
        { name: "A", items: ["x", "y"] },
        { name: "B", items: [] },
      ],
    })).toBe("[A/root:0=x;1=y;][B/root:empty]");
  });

  test("each else also handles missing and non-array values", () => {
    expect(render("{{#each value}}bad{{else}}empty{{/each}}", {})).toBe("empty");
    expect(render("{{#each value}}bad{{else}}empty{{/each}}", { value: "no" })).toBe("empty");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("before {{value}}", { value: { nested: true } })).toThrow(
      "Cannot render object value as text at line 1, column 8",
    );
  });

  test.each([
    ["{{#wat x}}{{/wat}}", "Unknown block \"wat\" at line 1, column 1"],
    ["{{else}}", "{{else}} outside a block at line 1, column 1"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate {{else}} at line 1, column 18"],
    ["{{#if x}}{{/each}}", "Mismatched closing block"],
    ["x\n{{#if x}}", "Unclosed {{#if}} block at line 2, column 1"],
    ["x\n{{value", "Unclosed tag at line 2, column 1"],
  ])("reports structural error for %s", (template, message) => {
    expect(() => render(template, {})).toThrow(message);
    try {
      render(template, {});
    } catch (error) {
      expect(error).toBeInstanceOf(TemplateError);
    }
  });
});

describe("CLI", () => {
  test("renders UTF-8 files to stdout", async () => {
    const directory = await import("node:fs/promises").then((fs) => fs.mkdtemp("/tmp/mini-template-"));
    const templatePath = `${directory}/template.txt`;
    const dataPath = `${directory}/data.json`;
    await Bun.write(templatePath, "Привет, {{name}}!");
    await Bun.write(dataPath, JSON.stringify({ name: "мир" }));

    const process = Bun.spawn(["bun", "run", "src/cli.ts", templatePath, dataPath], {
      stdout: "pipe",
      stderr: "pipe",
    });
    expect(await process.exited).toBe(0);
    expect(await new Response(process.stdout).text()).toBe("Привет, мир!");
    expect(await new Response(process.stderr).text()).toBe("");
  });

  test("reports errors on stderr and exits non-zero", async () => {
    const process = Bun.spawn(["bun", "run", "src/cli.ts"], {
      stdout: "pipe",
      stderr: "pipe",
    });
    expect(await process.exited).not.toBe(0);
    expect(await new Response(process.stdout).text()).toBe("");
    expect(await new Response(process.stderr).text()).toContain("Usage:");
  });
});

import { render } from "./engine";

async function main(): Promise<void> {
  const args = Bun.argv.slice(2);
  if (args.length !== 2) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [templatePath, dataPath] = args;
  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

try {
  await main();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`mini-template: ${message}\n`);
  process.exitCode = 1;
}

